const people = [{name: 'Alice', age: 25}, {name: 'Bob', age: 30}, {name: 'Charlie', age: 25}];
const byAge = people.reduce((acc, p) => {
  acc[p.age] = acc[p.age] || [];
  acc[p.age].push(p.name);
  return acc;
}, {});
console.log(byAge);
